# Code generated by Claude
"""The follower of the navigation core: Regulated Pure Pursuit along a verified route (overnight queue stage 3; navigation proposal section 6 (N8, N9); decisions-log M149; Nav2's names).

    ctl = route_controller(NAV_CFG, plan_fn, final_ctl, clearance_at=None, max_ang=0.4)
    ctl["reset"](x, y, yaw); commands, status = ctl["step"](obs, t, dt)       # the same interface as staging_source._pose_controller

`plan_fn(x, y, yaw)` gives a route (src/nav_smooth.plan_route's dict). The follower: turns in place when the heading is more than `rotate_to_heading_min_angle` off the path's tangent; otherwise pure pursuit
on the lookahead point (the lookahead is the speed times `lookahead_time`, kept between `min_lookahead_dist` and `max_lookahead_dist`), the yaw rate v * (kappa_path + k_fb * (kappa_pursuit - kappa_path))
(the path's curvature fed forward; k_fb = 1 is Nav2's plain pursuit), the speed regulated down for curvature, near obstacles (`clearance_at`), near the path's end and by the braking rule sqrt(2 a d),
and slewed by the acceleration limits. A cross-track error above `track_tol` stops the base, replans from where it is (up to `max_replans` times per approach) and goes on; more replans, or no route, is a failure
for the operator (N-Q5, M057): S["fail"], S["fail_kind"] ("no path", "replans used up", "final"). The last centimetres are the final controller's (today's go-to-pose controller: aim 1 cm / 0.5 degrees, at rest
for drive_settle_s, corrective re-approaches), started when the path's end is reached.

Contents:
    route_controller.
"""

import math

import numpy as np


def _wrap(a):
    return (a + math.pi) % (2 * math.pi) - math.pi


def _slew(cur, target, up, down, dt):
    """One step of cur toward target, limited to up * dt when the magnitude grows and down * dt otherwise."""
    d = target - cur
    lim = (up if (abs(target) > abs(cur) and cur * target >= 0) else down) * dt
    return cur + max(-lim, min(lim, d))


def route_controller(cfg, plan_fn, final_ctl, clearance_at=None, max_ang=0.4):
    """Makes the route follower.

    Args:
        cfg (dict): NAV_CFG.
        plan_fn (callable): plan_fn(x, y, yaw) -> route dict ("ok", "reason", "samples" (N, 5: x, y, heading, curvature, s), "turns", "lead_in_m", "lead_out_m", "smoothed", "max_curvature", "length").
        final_ctl (dict): The go-to-pose controller of the approach spot (staging_source._pose_controller): "reset", "step", "S".
        clearance_at (callable or None): clearance_at(x, y) -> distance from the robot's inscribed edge to the nearest obstacle, metres, for the cost scaling. None switches it off.
        max_ang (float): The largest yaw rate of the pursuit, rad/s. Defaults to 0.4.

    Returns:
        dict: "reset" (callable): reset(x, y, yaw); "step" (callable): step(obs, t, dt) -> (commands, status) with status "running", "arrived" or "failed";
            "S" (dict): "leg" ("PLAN", "FOLLOW", "BRAKE", "FINAL"), "twist", "route" (the current route), "routes" (every route planned), "replans", "first_turn", "final_turn", "reapproach", "fail", "fail_kind",
            "aim_missed", "cross_track_max" (m), "max_curvature_used" (1/m), "plan_seconds".
    """
    S = {"leg": "PLAN", "twist": (0.0, 0.0), "route": None, "routes": [], "replans": 0, "first_turn": None, "final_turn": None, "reapproach": 0, "fail": None, "fail_kind": None,
         "aim_missed": False, "cross_track_max": 0.0, "i": 0, "rotating": False, "plan_seconds": 0.0, "line": None, "ok_since": None, "trace": [], "ticks": 0}

    def reset(x, y, yaw):
        S.update(leg="PLAN", twist=(0.0, 0.0), route=None, routes=[], replans=0, first_turn=None, final_turn=None, reapproach=0, fail=None, fail_kind=None, aim_missed=False,
                 cross_track_max=0.0, i=0, rotating=False, plan_seconds=0.0, trace=[], ticks=0)

    def plan(x, y, yaw):
        import time
        t0 = time.time()
        r = plan_fn(x, y, yaw)
        S["plan_seconds"] += time.time() - t0
        S["routes"].append({k: r[k] for k in ("ok", "reason", "lead_in_m", "lead_out_m", "smoothed", "repairs", "max_curvature", "length", "turns")})
        if not r["ok"]:
            S["fail"], S["fail_kind"] = f"no route from ({x:.2f}, {y:.2f}): {r['reason']}", "no path"
            return False
        S["route"], S["i"], S["rotating"] = r, 0, False
        return True

    def project(R, x, y):
        """The nearest point on the route from the current segment on: (segment index, arc length, distance, tangent heading, curvature)."""
        P = R["samples"]
        best = None
        for i in range(S["i"], min(S["i"] + 60, len(P) - 1)):
            a, b = P[i, :2], P[i + 1, :2]
            ab = b - a
            L2 = float(ab @ ab)
            u = 0.0 if L2 < 1e-12 else max(0.0, min(1.0, float(((x - a[0]) * ab[0] + (y - a[1]) * ab[1]) / L2)))
            q = a + u * ab
            d = math.hypot(x - q[0], y - q[1])
            if best is None or d < best[2] - 1e-9:
                best = (i, float(P[i, 4] + u * (P[i + 1, 4] - P[i, 4])), d, float(P[i + 1, 2] if u > 0.5 else P[i, 2]), float(P[i, 3] + u * (P[i + 1, 3] - P[i, 3])))
        if best is None:
            i = len(P) - 2
            return i, float(P[-1, 4]), math.hypot(x - P[-1, 0], y - P[-1, 1]), float(P[-1, 2]), float(P[-1, 3])
        return best

    def point_at(R, s):
        P = R["samples"]
        if s >= P[-1, 4]:
            h = P[-1, 2]
            e = s - P[-1, 4]
            return P[-1, 0] + e * math.cos(h), P[-1, 1] + e * math.sin(h)
        return float(np.interp(s, P[:, 4], P[:, 0])), float(np.interp(s, P[:, 4], P[:, 1]))

    def turn_rate(err):
        w = math.sqrt(2 * cfg["max_angular_accel"] * max(abs(err) - 0.01, 0.0))
        return math.copysign(max(min(w, cfg["rotate_to_heading_angular_vel"], max_ang), 0.03), err)

    def step(obs, t, dt):
        S["twist"] = tuple(float(v) for v in obs["applied"]["twist"])
        x, y, yaw = obs["base_pose"]
        lin, ang = S["twist"]
        if S["leg"] == "PLAN":
            if not plan(x, y, yaw):
                return [], "failed"
            S["leg"] = "FOLLOW"
        if S["leg"] == "FINAL":
            cmds, status = final_ctl["step"](obs, t, dt)
            F = final_ctl["S"]
            S.update(final_turn=F["final_turn"], reapproach=F["reapproach"], aim_missed=F["aim_missed"], twist=F["twist"])
            if status == "failed":
                S["fail"], S["fail_kind"] = F["fail"], "final"
            return cmds, status
        R = S["route"]
        i, s, d, th, kff = project(R, x, y)
        S["i"] = i
        S["cross_track_max"] = max(S["cross_track_max"], d)
        S["ticks"] += 1
        if S["ticks"] % 75 == 1:                                         # a sparse trace (every 0.5 s) for the report: time, pose, leg, distance to the route, applied twist
            S["trace"].append([round(t, 2), round(x, 3), round(y, 3), round(yaw, 3), S["leg"] + ("+rot" if S["rotating"] else ""), round(d, 3), round(lin, 3), round(ang, 3)])
        remaining = float(R["samples"][-1, 4] - s)
        if S["leg"] == "FOLLOW" and d > cfg["track_tol"]:
            S["leg"] = "BRAKE"
        if S["leg"] == "BRAKE":
            lin = _slew(lin, 0.0, cfg["max_linear_accel"], cfg["max_linear_decel"], dt)
            ang = _slew(ang, 0.0, cfg["max_angular_accel"], cfg["max_angular_accel"], dt)
            S["twist"] = (lin, ang)
            if abs(lin) < 1e-9 and abs(ang) < 1e-9:
                S["replans"] += 1
                if S["replans"] > cfg["max_replans"]:
                    S["fail"], S["fail_kind"] = f"the base left the route by more than {cfg['track_tol'] * 100:.0f} cm and {cfg['max_replans']} replans are used up", "replans used up"
                    return [], "failed"
                if not plan(x, y, yaw):
                    return [], "failed"
                S["leg"] = "FOLLOW"
            return [{"mode": "base", "twist": (lin, ang)}], "running"
        if remaining <= 0.5 * cfg.get("end_tol", 0.01):                 # the path's end: the final controller takes over (it sees the base at rest or nearly)
            S["leg"] = "FINAL"
            final_ctl["reset"](x, y, yaw)
            final_ctl["S"]["twist"] = S["twist"]
            return step(obs, t, dt)
        err = _wrap(th - yaw)
        if S["first_turn"] is None:
            S["first_turn"] = math.degrees(err)
        if abs(err) > cfg["rotate_to_heading_min_angle"] and abs(lin) < 0.02:
            S["rotating"] = True
        if S["rotating"] and abs(err) < math.radians(2.0):
            S["rotating"] = False
        if S["rotating"]:
            lin_t, ang_t = 0.0, turn_rate(err)
        else:
            v = cfg["desired_linear_vel"]
            L = max(cfg["min_lookahead_dist"], min(cfg["max_lookahead_dist"], abs(lin) * cfg["lookahead_time"])) if cfg["use_velocity_scaled_lookahead_dist"] else cfg["max_lookahead_dist"]
            lx, ly = point_at(R, s + L)
            dx, dy = lx - x, ly - y
            xl, yl = math.cos(yaw) * dx + math.sin(yaw) * dy, -math.sin(yaw) * dx + math.cos(yaw) * dy
            kp = 2.0 * yl / max(L * L, 1e-9) if xl > 0 else math.copysign(1.0 / max(cfg["regulated_linear_scaling_min_radius"] * 0.25, 1e-9), yl)
            radius = 1.0 / max(abs(kp), 1e-9)
            if radius < cfg["regulated_linear_scaling_min_radius"]:
                v = max(v * radius / cfg["regulated_linear_scaling_min_radius"], cfg["regulated_linear_scaling_min_speed"])
            if clearance_at is not None:
                dist = clearance_at(x, y)
                if dist < cfg["cost_scaling_dist"]:
                    v = max(min(v, v * cfg["cost_scaling_gain"] * dist / cfg["cost_scaling_dist"]), cfg["regulated_linear_scaling_min_speed"])
            if remaining < cfg["approach_velocity_scaling_dist"]:
                v = max(min(v, v * remaining / cfg["approach_velocity_scaling_dist"]), cfg["min_approach_linear_velocity"])
            v = min(v, max(math.sqrt(2 * cfg["max_linear_decel"] * max(remaining - 0.25 * cfg.get("end_tol", 0.01), 0.0)), cfg["min_approach_linear_velocity"]))
            lin_t = v
            ang_t = v * (kff + cfg["k_fb"] * (kp - kff))
            ang_t = max(-max_ang, min(max_ang, ang_t))
            S["max_curvature_used"] = max(S.get("max_curvature_used", 0.0), abs(kp))
        lin = _slew(lin, lin_t, cfg["max_linear_accel"], cfg["max_linear_decel"], dt)
        ang = _slew(ang, ang_t, cfg["max_angular_accel"], cfg["max_angular_accel"], dt)
        S["twist"] = (lin, ang)
        return [{"mode": "base", "twist": (lin, ang)}], "running"

    return {"reset": reset, "step": step, "S": S}
